// The Worker's entry: OpenNext's Next.js handler, plus what Next cannot do.
//
// .open-next/worker.js is generated by `opennextjs-cloudflare build` and
// serves the whole Next app. Two things go around it:
//
//   - the Durable Object classes, which have to be exports of the entry
//     module for wrangler to bind them (workers/jamRoom.ts, workers/composeJob.ts,
//     and OpenNext's own revalidation queue);
//   - a jam room's WebSocket, which is an upgrade a Next route handler has no
//     way to hand on, so it is routed to its room here, before Next sees it.

// @ts-ignore generated at build time
import { default as handler } from "./.open-next/worker.js";
import { JamRoom, JAM_ROOM_PATH, jamRoomName } from "./workers/jamRoom";

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.startsWith(JAM_ROOM_PATH)) {
      const room = jamRoomName(url.pathname);
      if (!room) return new Response("no such room", { status: 404 });
      if (request.headers.get("upgrade")?.toLowerCase() !== "websocket")
        return new Response("expected a websocket", { status: 426 });
      return env.JAM_ROOM.get(env.JAM_ROOM.idFromName(room)).fetch(request);
    }
    return handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<CloudflareEnv>;

export { JamRoom };
export { ComposeJob, ComposeLimits } from "./workers/composeJob";
// @ts-ignore generated at build time
export { DOQueueHandler } from "./.open-next/worker.js";
